/* Parameter sweeps and snapshots operate on the experiment's native controls. */
(()=>{'use strict';const tools=new WeakMap(),motion=matchMedia('(prefers-reduced-motion: reduce)'),running=new Map();
const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
function text(n){const c=n.cloneNode(true);c.querySelectorAll('.inline-math[data-inline-raw]').forEach(n=>n.replaceWith(document.createTextNode(n.dataset.inlineRaw)));c.querySelectorAll('.katex').forEach(n=>n.replaceWith(document.createTextNode(n.querySelector('.katex-html')?.textContent||'')));c.querySelectorAll('output,.glossary-ui').forEach(n=>n.remove());return c.textContent.trim();}
function cells(page){return [...page.querySelectorAll('.readout-row>div,.readouts>div,.extension-readouts>div')].filter(n=>n.querySelector('strong')).map(n=>({label:text(n.querySelector('span')||n),value:text(n.querySelector('strong'))}));}
const numeric=s=>{const raw=s.replaceAll(',','').replace(/%$/,'').trim();return /^[+−-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+−-]?\d+)?$/i.test(raw)?Number(raw.replace('−','-')):null;};
function stop(page){const run=running.get(page);if(!run)return;cancelAnimationFrame(run.frame);running.delete(page);run.button.textContent='扫描所选参数';run.button.setAttribute('aria-pressed','false');}
function attach(page){if(tools.has(page))return;const inputs=[...page.querySelectorAll('input[type=range]')];if(!inputs.length)return;
const details=el('details','lab-workbench'),summary=el('summary','','参数扫描与读数对照'),row=el('div','lab-workbench-actions'),label=el('label','','扫描参数'),select=el('select'),sweep=el('button','','扫描所选参数'),pin=el('button','','记录当前读数'),clear=el('button','','清除记录'),progress=el('progress'),note=el('p','lab-tool-note','扫描只改变所选参数；动画进度不是物理时间。可随时拖动原滑块接管。'),results=el('div','lab-snapshot');
select.setAttribute('aria-label','选择扫描参数');for(const input of inputs){const option=new Option(text(page.querySelector(`label[for="${CSS.escape(input.id)}"]`)||input.parentElement),input.id);select.append(option);}label.append(select);for(const b of [sweep,pin,clear])b.type='button';sweep.setAttribute('aria-pressed','false');clear.hidden=true;progress.max=1;progress.value=0;progress.setAttribute('aria-label','参数扫描进度');row.append(label,sweep,pin,clear);details.append(summary,row,progress,note,results);const footer=page.querySelector('.reader-page-footer');if(footer)footer.before(details);else page.append(details);let saved;
function update(){if(!saved)return;const now=cells(page),table=el('table','lab-comparison-table'),head=el('thead'),hr=el('tr');for(const title of ['读数','记录','当前','差值'])hr.append(el('th','',title));head.append(hr);table.append(head);const body=el('tbody');now.forEach((cell,i)=>{const old=saved.rows[i];if(!old)return;const row=el('tr'),a=numeric(old.value),b=numeric(cell.value),delta=a===null||b===null?'—':(b-a).toLocaleString('zh-CN',{maximumSignificantDigits:5});for(const value of [cell.label,old.value,cell.value,delta])row.append(el('td','',value));body.append(row);});table.append(body);const params=el('p','lab-tool-note','已记录：'+saved.params);results.replaceChildren(params,table);window.BookMath?.typeset(results);}
pin.onclick=()=>{saved={rows:cells(page),params:inputs.map(n=>(select.querySelector(`option[value="${CSS.escape(n.id)}"]`)?.textContent||n.id)+'='+n.value).join('；')};if(!saved.rows.length){note.textContent='本页没有汇总读数；可在图表工具中固定当前曲线。';return;}clear.hidden=false;pin.textContent='更新记录';update();};clear.onclick=()=>{saved=undefined;results.replaceChildren();clear.hidden=true;pin.textContent='记录当前读数';};
sweep.onclick=()=>{if(running.has(page)){stop(page);return;}const input=document.getElementById(select.value),min=+input.min,max=+input.max,step=+input.step||1,apply=t=>{input.value=Math.min(max,min+Math.round((max-min)*t/step)*step);input.dispatchEvent(new Event('input',{bubbles:true}));progress.value=t;};if(motion.matches){apply(1);input.dispatchEvent(new Event('change',{bubbles:true}));note.textContent='已按减少动态效果设置直接显示扫描终点。';return;}const run={button:sweep,frame:0,start:performance.now(),last:0};running.set(page,run);sweep.textContent='停止扫描';sweep.setAttribute('aria-pressed','true');const tick=now=>{if(!page.classList.contains('is-active')||document.hidden||motion.matches){stop(page);return;}const t=Math.min(1,(now-run.start)/8000);if(now-run.last>=180||t===1){apply(t);run.last=performance.now();}if(t<1)run.frame=requestAnimationFrame(tick);else{stop(page);input.dispatchEvent(new Event('change',{bubbles:true}));}};run.frame=requestAnimationFrame(tick);};
inputs.forEach(n=>{n.addEventListener('pointerdown',()=>stop(page));n.addEventListener('keydown',()=>stop(page));});select.onchange=()=>stop(page);const observer=new MutationObserver(()=>{if(saved)update();});page.querySelectorAll('.readout-row,.readouts,.extension-readouts').forEach(n=>observer.observe(n,{subtree:true,childList:true,characterData:true}));tools.set(page,{update});}
function start(){document.querySelectorAll('.reader-slide').forEach(attach);}
document.addEventListener('visibilitychange',()=>{if(document.hidden)[...running.keys()].forEach(stop);});document.addEventListener('reader:pagechange',()=>{for(const page of running.keys())if(!page.classList.contains('is-active'))stop(page);start();});motion.addEventListener('change',()=>{if(motion.matches)[...running.keys()].forEach(stop);});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();
